import functools

def solution(input_str):
    lines = input_str.strip().split('\n')
    s1 = lines[0]
    s2 = lines[1]
    virus = lines[2]

    m, n, v_len = len(s1), len(s2), len(virus)

    # KMP preprocessing for virus
    pi = [0] * v_len
    j = 0
    for i in range(1, v_len):
        while j > 0 and virus[i] != virus[j]:
            j = pi[j - 1]
        if virus[i] == virus[j]:
            j += 1
        pi[i] = j

    # Precompute next_state table for DP
    # next_state[i][j] = length of longest prefix of virus that is a suffix of (virus[:j] + char j)
    nxt = [[0] * (v_len + 1) for _ in range(26)]
    for c_code in range(26):
        for state in range(v_len + 1):
            if state == v_len:
                # Can't transition from full match
                nxt[c_code][state] = 0
            else:
                c = chr(ord('A') + c_code)
                temp = state
                while temp > 0 and virus[temp] != c:
                    temp = pi[temp - 1]
                if virus[temp] == c:
                    temp += 1
                nxt[c_code][state] = min(temp, v_len)

    # dp[i][j][k] = longest LCS length using s1[:i], s2[:j] with virus prefix matched k
    # Initialize with -1 (unreachable)
    @lru_cache(None)
    def dp(i, j, k):
        if i == m or j == n:
            return 0

        # Option 1: skip character in s1 or s2
        res = max(dp(i + 1, j, k), dp(i, j + 1, k))

        # Option 2: if s1[i] == s2[j], include it
        if s1[i] == s2[j]:
            c = ord(s1[i]) - ord('A')
            new_k = nxt[c][k]
            if new_k < v_len:  # Valid state (not full match)
                res = max(res, 1 + dp(i + 1, j + 1, new_k))

        return res

    # Now compute answer
    max_len = dp(0, 0, 0)

    if max_len == 0:
        return "0"

    # Reconstruct the solution
    i, j, k = 0, 0, 0
    result = []

    while i < m and j < n:
        # Try to include matching character if possible
        if s1[i] == s2[j]:
            c = ord(s1[i]) - ord('A')
            new_k = nxt[c][k]
            if new_k < v_len:
                if dp(i + 1, j + 1, new_k) + 1 == dp(i, j, k):
                    result.append(c)
                    k = new_k
                    i = i + 1
                    j = j + 1
                    continue

        # Choose the better direction (use try-except or direct check)
        if dp(i + 1, j, k) >= dp(i, j + 1, k):
            i += 1
        else:
            j += 1

    return ''.join(result[::-1])

