from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ''

    n, m = map(int, lines[0].split())

    if m == n - 1:
        return ''

    edges = []
    for i in range(m):
        u, v, w = map(int, lines[1 + i].split())
        edges.append((u - 1, v - 1, w, i))

    # Kruskal's algorithm for MST
    edges_sorted = sorted(edges, key=lambda x: x[2])

    parent = list(range(n))
    rank = [0] * n
    mst_edge_indices = set()

    def find(i):
        root = i
        while parent[root] != root:
            root = parent[root]
        curr = i
        while parent[curr] != root:
            nxt = parent[curr]
            parent[curr] = root
            curr = nxt
        return root

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            if rank[root_i] < rank[root_j]:
                root_i, root_j = root_j, root_i
            parent[root_j] = root_i
            if rank[root_i] == rank[root_j]:
                rank[root_i] += 1
            return True
        return False

    for u, v, w, _ in edges_sorted:
        if union(u, v):
            mst_edge_indices.add((min(u, v), max(u, v)))

    # Build adjacency list for MST (starting from node 0)
    adj = [[] for _ in range(n)]
    for u, v, w, _ in edges:
        if (min(u, v), max(u, v)) in mst_edge_indices:
            adj[u].append((v, w))
            adj[v].append((u, w))

    # BFS to build tree structure for LCA and path max queries
    depth = [0] * n
    up = [[-1] * 20 for _ in range(n)]
    max_edge_table = [[-1] * 20 for _ in range(n)]

    queue = deque([0])
    visited = [False] * n
    visited[0] = True

    while queue:
        u = queue.popleft()
        for v, w in adj[u]:
            if not visited[v]:
                visited[v] = True
                depth[v] = depth[u] + 1
                up[v][0] = u
                max_edge_table[v][0] = w
                queue.append(v)

    # Binary lifting table construction
    for j in range(1, 20):
        for i in range(n):
            if up[i][j - 1] != -1:
                up[i][j] = up[up[i][j - 1]][j - 1]
                max_edge_table[i][j] = max(max_edge_table[i][j - 1], 
                                           max_edge_table[up[i][j - 1]][j - 1])

    def get_max_on_path(u, v):
        if u == v:
            return -1

        # Get LCA and compute max on path
        u_orig, v_orig = u, v

        # Ensure u is deeper
        if depth[u] < depth[v]:
            u, v = v, u

        # Lift u to v's depth
        for j in range(19, -1, -1):
            if depth[u] - (1 << j) >= depth[v]:
                u = up[u][j]

        if u == v:
            return -1  # Should not happen for non-tree edges

        # Lift both to just below LCA
        for j in range(19, -1, -1):
            if up[u][j] != up[v][j]:
                u = up[u][j]
                v = up[v][j]

        # Include final edge to LCA
        return max(max_edge_table[u_orig][0], max_edge_table[v_orig][0])

    # Find answers for non-MST edges
    mst_edge_set = set(mst_edge_indices)
    result = []

    for u, v, w, idx in edges:
        if (min(u, v), max(u, v)) not in mst_edge_set:
            path_max = get_max_on_path(u, v)
            result.append(str(path_max))

    return '\n'.join(result) + '\n'

