def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "0\n"

    first_line = lines[0].split()
    N, M, K = int(first_line[0]), int(first_line[1]), int(first_line[2])

    transformers = []
    for i in range(1, K + 1):
        parts = lines[i].split()
        x, y, d, t, e = int(parts[0]), int(parts[1]), int(parts[2]), int(parts[3]), int(parts[4])
        transformers.append({'x': x, 'y': y, 'd': d, 't': t, 'e': e})

    n_steps = N + M - 2
    if n_steps == 0:
        # Single cell (0,0) to (0,0)
        total_cost = 0
        for trans in transformers:
            if 0 >= trans['t']:
                offset = 0 - trans['t']
                phase = offset % 4
                if phase == 0:
                    tx, ty = trans['x'], trans['y']
                elif phase == 1:
                    tx, ty = trans['x'] + trans['d'], trans['y'] - trans['d']
                elif phase == 2:
                    tx, ty = trans['x'] + trans['d'], trans['y']
                elif phase == 3:
                    tx, ty = trans['x'], trans['y'] + trans['d']
                if 0 == tx and 0 == ty:
                    total_cost += trans['e']
        return str(total_cost) + "\n"

    # Precompute the transformer costs for each cell and time
    # For each cell (r, c), determine which transformers exist at time r+c
    cell_transformer_costs = {}

    for r in range(N):
        for c in range(M):
            time_in_cell = r + c
            costs = []
            for trans in transformers:
                if time_in_cell >= trans['t']:
                    offset = time_in_cell - trans['t']
                    phase = offset % 4
                    if phase == 0:
                        tx, ty = trans['x'], trans['y']
                    elif phase == 1:
                        tx, ty = trans['x'] + trans['d'], trans['y'] - trans['d']
                    elif phase == 2:
                        tx, ty = trans['x'] + trans['d'], trans['y']
                    elif phase == 3:
                        tx, ty = trans['x'], trans['y'] + trans['d']

                    if r == tx and c == ty:
                        costs.append(trans['e'])

            if costs:
                cell_transformer_costs[(r, c)] = sum(costs)

    # DP: dp[r][c] = minimum energy to reach cell (r, c)
    # dp initialized with infinity, except dp[0][0]
    dp = [[float('inf')] * M for _ in range(N)]

    dp[0][0] = cell_transformer_costs.get((0, 0), 0)

    # Fill first row
    for c in range(1, M):
        dp[0][c] = dp[0][c-1] + cell_transformer_costs.get((0, c), 0)

    # Fill first column
    for r in range(1, N):
        dp[r][0] = dp[r-1][0] + cell_transformer_costs.get((r, 0), 0)

    # Fill rest of matrix
    for r in range(1, N):
        for c in range(1, M):
            cell_cost = cell_transformer_costs.get((r, c), 0)
            dp[r][c] = min(dp[r-1][c], dp[r][c-1]) + cell_cost

    # Check if destination is reachable
    return str(dp[N-1][M-1]) + "\n"

