def solution(params):
    a, b, l, r = map(int, params.split())
    # Period = a + b (cycle for B and computer turns)
    Period = a + b

    # Count initial positions (1 to a) within [l, r]
    if l <= a:
        count_initial = min(r, a) - l + 1
    else:
        count_initial = 0

    # Count computer positions in [l, r]
    # Only p such that p > a and (p - a - 1) % Period >= b are computer
    # Compute B positions first
    def b_count_for_n(n):
        """Returns number of B positions in [a+1, n]"""
        if n <= a:
            return 0
        total_k = n - a  # p runs from a+1 to n, so k = p-a-1 runs from 0 to total_k-1
        periods = total_k // Period
        remainder = total_k % Period
        return periods * b + min(remainder, b)

    # B positions in [start, end] = B_count(end) - B_count(start - 1)
    start_computer = max(l, a + 1)
    end_computer = r

    if start_computer <= end_computer:
        total_in_computer = end_computer - start_computer + 1
        B_in_range = b_count_for_n(end_computer) - b_count_for_n(start_computer - 1)
        computer_in_range = total_in_computer - B_in_range
    else:
        computer_in_range = 0

    # Determine answer
    if computer_in_range > 0:
        answer = count_initial + 1
    else:
        answer = max(1, count_initial)

    return str(answer)

