        for v in adj[u]:
            if v not in visited:
                parents[v] = u
                visited.add(v)
                queue.append(v)
                order.append(v)

    # Compute subtree sizes (post-order)
    subtree_size = {node: 1 for node in range(1, N + 1)}
    for node in reversed(order):
        p = parents[node]
        if p != -1:
            subtree_size[p] += subtree_size[node]

    # Find centroid
    centroid = 1
    min_max_comp = float('inf')

    for node in range(1, N + 1):
        max_comp = max(subtree_size[node], N - subtree_size[node])
        for child in adj[node]:
            if child != parents[node]:
                max_comp = max(max_comp, subtree_size[child])

        if max_comp < min_max_comp:
            min_max_comp = max_comp
            centroid = node

