from collections import deque

def solution(input_string):
    lines = input_string.strip().split('\n')

    if not lines:
        return ""

    parts = lines[0].split()
    n, m = int(parts[0]), int(parts[1])

    if len(parts) >= 4:
        swapLR = int(parts[2])
        swapUD = int(parts[3])
        grid_lines = lines[2:2+n]
    else:
        swapLR = 0
        swapUD = 0
        grid_lines = lines[1:1+n]

    grid = [list(line) for line in grid_lines]

    # Find finish position
    finish_pos = None
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 'F':
                finish_pos = (r, c)
                break
        if finish_pos:
            break

    # Default direction mappings
    dirs_map = {
        'U': (-1, 0),
        'D': (1, 0),
        'L': (0, -1),
        'R': (0, 1)
    }

    # Adjust if L and R are swapped
    if swapLR:
        dirs_map['L'] = (0, 1)
        dirs_map['R'] = (0, -1)

    # Adjust if U and D are swapped
    if swapUD:
        dirs_map['U'] = (1, 0)
        dirs_map['D'] = (-1, 0)

    # BFS to find shortest safe path to finish
    started = (0, 0)
    visited = {started}
    queue = deque([(started, "")])
    result = None

    while queue:
        pos, path = queue.popleft()
        r, c = pos

        if pos == finish_pos:
            result = path
            break

        for move, (dr, dc) in dirs_map.items():
            nr, nc = r + dr, c + dc
            # Valid cell within bounds (not dangerous)
            if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] != '*':
                new_pos = (nr, nc)
                if new_pos not in visited:
                    visited.add(new_pos)
                    queue.append((new_pos, path + move))

    return result if result else ""

