import sys
from functools import lru_cache

def get_digits_with_counts(n):
    """Return a set of unique digits in n, plus sorted list of unique digits."""
    if n == 0:
        return {0}, [0]
    digits = set()
    sorted_digits = []
    for d in str(n):
        digits.add(int(d))
        sorted_digits.append(int(d))
    return digits, sorted(set(digits))

@lru_cache(maxsize=None)
def min_ops(n):
    if n == 0:
        return 0

    # Get all unique digits in n
    digits = set(int(d) for d in str(n))

    # Try subtracting each digit and find minimum
    min_result = float('inf')
    for d in digits:
        if d == 0:
            continue
        result = min_ops(n - d)
        if result != float('inf'):
            min_result = min(min_result, result + 1)

    return min_result if min_result != float('inf') else 0

