            matrix.append(row)
            idx += n

        operations = data[idx] if idx < len(data) else ""
        idx += 1

        if not operations:
            results.append('\n'.join(' '.join(map(str, row)) for row in matrix))
            continue

        current = [row[:] for row in matrix]

        # Operation R: Right shift columns
        def apply_R(matrix):
            return [[matrix[i][(j - 1 + n) % n] for j in range(n)] for i in range(n)]

        # Operation L: Left shift columns  
        def apply_L(matrix):
            return [[matrix[i][(j + 1) % n] for j in range(n)] for i in range(n)]

        # Operation D: Down shift rows
        def apply_D(matrix):
            return [[matrix[(i - 1 + n) % n][j] for j in range(n)] for i in range(n)]

        # Operation U: Up shift rows
        def apply_U(matrix):
            return [[matrix[(i + 1) % n][j] for j in range(n)] for i in range(n)]

        # Operation I: Invert each row permutation
        def apply_I(matrix):
            new = [[0] * n for _ in range(n)]
            for i in range(n):
                inv = [0] * n
                for j in range(n):
                    inv[matrix[i][j] - 1] = j
                new[i] = inv
            return new

        # Operation C: Invert each column permutation
        def apply_C(matrix):
            new = [[0] * n for _ in range(n)]
            for j in range(n):
                inv = [0] * n
                for i in range(n):
                    inv[matrix[i][j] - 1] = i
                for i in range(n):
                    new[i][j] = inv[i]
            return new

        for op in operations:
            if op == 'R':
                current = apply_R(current)
            elif op == 'L':
                current = apply_L(current)
            elif op == 'D':
                current = apply_D(current)
            elif op == 'U':
                current = apply_U(current)
            elif op == 'I':
                current = apply_I(current)
            elif op == 'C':
                current = apply_C(current)

        results.append('\n'.join(' '.join(map(str, row)) for row in current))

    return '\n'.join(results)


