    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Grid representation
    grid = [['.' for _ in range(m)] for _ in range(n)]

    if n == 0 or m == 0:
        return "0\n" + "".join(["\n"] * n)

    best_count = 0

    # T-shape patterns in 4 orientations (as local offsets from center)
    # Each pattern is 5 cells forming a T shape
    patterns = [
        # Pattern reference - stored as (center_row, center_col) plus offsets
        # There are 4 orientations, each placing 5 cells
        lambda r, c: [(r, c), (r, c+1), (r, c+2), (r+1, c+1), (r+2, c+1)],    # T pointing down
        lambda r, c: [(r, c+1), (r+1, c), (r+1, c+1), (r+1, c+2), (r+2, c+1)],  # T pointing up
        lambda r, c: [(r, c), (r+1, c), (r+2, c), (r+1, c+1), (r+1, c+2)],     # T pointing right
        lambda r, c: [(r, c+1), (r+1, c), (r+1, c+1), (r+1, c+2), (r+2, c+1)],  # T pointing left (symmetric)
    ]

    def get_cells(r, c, pattern_idx):
        return [(r + dr, c + dc) for dr, dc in patterns[pattern_idx](0, 0)]

    def is_valid(r, c, cells):
        for cr, cc in cells:
            if not (0 <= cr < n and 0 <= cc < m) or grid[cr][cc] != '.':
                return False
        return True

    def place_piece(cells, char):
        for r, c in cells:
            grid[r][c] = char

    def remove_piece(cells):
        for r, c in cells:
            grid[r][c] = '.'

    def solve(idx, depth, char_idx):
        nonlocal best_count

        if idx > n * m:
            if depth > best_count:
                best_count = depth

        if idx == 0:
            return

        r, c = idx // m, idx % m

        # Try to place a piece starting at current position (0,0)
        if idx < n * m:
            for pidx in range(4):
                cells = [(r + dr, c + dc) for dr, dc in patterns[pidx](0, 0)]
                if is_valid(r, c, cells):
                    # Create actual coordinates
                    cell_coords = []
                    for dr, dc in patterns[pidx](0, 0):
