import sys

def solution(input_str):
    n, m = map(int, input_str.strip().split('\n')[0].split())

    if n * m == 0:
        return "0\n\n"

    grid = [['.' for _ in range(m)] for _ in range(n)]

    patterns = [
        [(0, 0), (0, 1), (0, 2), (1, 1), (2, 1)],
        [(0, 1), (1, 0), (1, 1), (1, 2), (2, 1)],
        [(0, 0), (1, 0), (2, 0), (1, 1), (1, 2)],
        [(0, 0), (1, 0), (1, 1), (2, 0), (2, 1)],
    ]

    def can_place(r, c, pat_idx):
        offsets = patterns[pat_idx]
        cells = [(r + dr, c + dc) for dr, dc in offsets]
        for tr, tc in cells:
            if not (0 <= tr < n and 0 <= tc < m):
                return False
        for tr, tc in cells:
            if grid[tr][tc] != '.':
                return False
        return True

    def apply(r, c, pat_idx, char_offset):
        offsets = patterns[pat_idx]
        for i, (dr, dc) in enumerate(offsets):
            grid[r + dr][c + dc] = chr(ord('A') + char_offset + i)

    def undo(r, c, pat_idx):
        offsets = patterns[pat_idx]
        for i, (dr, dc) in enumerate(offsets):
            grid[r + dr][c + dc] = '.'

    best_c = 0
    best_b = [row[:] for row in grid]

    def dfs(idx, depth, char_idx):
        nonlocal best_c, best_b
        if idx == n * m:
            if depth > best_c:
                best_c = depth
                best_b = [row[:] for row in grid]
            return

        r, c = idx // m, idx % m

        for pidx in range(4):
            if can_place(idx // m, idx % m, pidx):
                apply(idx // m, idx % m, pidx, char_idx)
                dfs(idx + 1, depth + 1, char_idx + 1)
                undo(idx // m, idx % m, pidx)

        dfs(idx + 1, depth, char_idx)

    dfs(0, 0, 0)

    return f"{best_c}\n" + "\n".join("".join(row) for row in best_b)

